WITH ranked AS (SELECT * FROM customers QUALIFY ROW_NUMBER() OVER (PARTITION BY city ORDER BY signup_date, id) = 1) SELECT CASE WHEN age >= 55 THEN 'HIGH' ELSE 'LOW' END AS age_tier, PERCENTILE_APPROX(credit_limit, ARRAY(0.25, 0.5, 0.75)) AS credit_limit_quartiles, COUNT(*) AS cnt, COUNT(*) FILTER (WHERE country = 'SG') AS sg_rows FROM ranked GROUP BY CASE WHEN age >= 55 THEN 'HIGH' ELSE 'LOW' END;
